"use client";
/* Dragon, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Dragon(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("dragon"); }, []);
  return React.createElement("piix-sprite", { "name": "dragon", ...piixAttrs(props) });
}

export default Dragon;
